mapper.sql:
l.tenant_id = #{tenantId} and l.member_id = #{memberId} and l.is_delete = 0

    and l.ledger_no like concat('%', #{query.ledgerNo}, '%')

and l.account_type = #{query.accountType}
and l.direction = #{query.direction}
and l.biz_type = #{query.bizType}
and l.ledger_status = #{query.ledgerStatus}
and l.invoice_status = #{query.invoiceStatus}
and l.create_time >= #{query.beginTime}
and l.create_time <= #{query.endTime}


        and l.direction = 1


        and (lower(l.biz_type) like '%express%' or lower(l.biz_type) like '%shipping%'
             or lower(l.biz_type) like '%delivery%' or l.biz_type like '%快递%' or l.biz_type like '%物流%')


        and (lower(l.biz_type) like '%withdraw%' or l.biz_type like '%提现%')


        and l.invoice_status is not null


        and l.ref_type is not null and l.ref_type != ''
